import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.ClgMjOt7.js";const f=JSON.parse('{"title":"検索機能 & ウォッチリスト","description":"タグ検索、各種フィルター、ソート、お気に入りタグ管理（ウォッチリスト）","frontmatter":{"title":"検索機能 & ウォッチリスト","description":"タグ検索、各種フィルター、ソート、お気に入りタグ管理（ウォッチリスト）"},"headers":[],"relativePath":"features/search.md","filePath":"features/search.md","lastUpdated":1786166106000}'),l={name:"features/search.md"};function i(d,e,c,s,n,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="検索機能-ウォッチリスト" tabindex="-1">検索機能 &amp; ウォッチリスト <a class="header-anchor" href="#検索機能-ウォッチリスト" aria-label="Permalink to &quot;検索機能 &amp; ウォッチリスト&quot;">​</a></h1><p>検索画面 (<code>SearchScreen</code>) では、多様なパラメータ指定による検索とウォッチリスト管理が行えます。</p><hr><h2 id="検索ターゲット-searchtarget" tabindex="-1">検索ターゲット (<code>SearchTarget</code>) <a class="header-anchor" href="#検索ターゲット-searchtarget" aria-label="Permalink to &quot;検索ターゲット (`SearchTarget`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">モード</th><th style="text-align:left;">指定型</th><th style="text-align:left;">説明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>タグ部分一致</strong></td><td style="text-align:left;"><code>PartialTags</code></td><td style="text-align:left;">指定したタグを含む作品を検索</td></tr><tr><td style="text-align:left;"><strong>タグ完全一致</strong></td><td style="text-align:left;"><code>ExactTag</code></td><td style="text-align:left;">タグが完全一致する作品のみ検索</td></tr><tr><td style="text-align:left;"><strong>タイトル・キャプション</strong></td><td style="text-align:left;"><code>TitleAndCaption</code></td><td style="text-align:left;">作品タイトルおよび説明文を対象としたテキスト検索</td></tr><tr><td style="text-align:left;"><strong>ユーザー検索</strong></td><td style="text-align:left;"><code>Users</code></td><td style="text-align:left;">ユーザー名および Pixiv ID でのユーザー検索</td></tr></tbody></table><hr><h2 id="絞り込み-ソートパラメータ" tabindex="-1">絞り込み &amp; ソートパラメータ <a class="header-anchor" href="#絞り込み-ソートパラメータ" aria-label="Permalink to &quot;絞り込み &amp; ソートパラメータ&quot;">​</a></h2><h3 id="ソート条件-searchsort" tabindex="-1">ソート条件 (<code>SearchSort</code>) <a class="header-anchor" href="#ソート条件-searchsort" aria-label="Permalink to &quot;ソート条件 (`SearchSort`)&quot;">​</a></h3><ul><li><code>DateDesc</code>: 投稿日時が新しい順</li><li><code>DateAsc</code>: 投稿日時が古い順</li><li><code>PopularDesc</code>: 人気順（Pixiv Premium アカウントまたは条件適合時）</li></ul><h3 id="期間指定-searchduration" tabindex="-1">期間指定 (<code>SearchDuration</code>) <a class="header-anchor" href="#期間指定-searchduration" aria-label="Permalink to &quot;期間指定 (`SearchDuration`)&quot;">​</a></h3><ul><li><code>All</code>: 全期間</li><li><code>WithinDay</code>: 24時間以内</li><li><code>WithinWeek</code>: 1週間以内</li><li><code>WithinMonth</code>: 1ヶ月以内</li></ul><h3 id="ブックマーク数フィルター-searchbookmarkfilter" tabindex="-1">ブックマーク数フィルター (<code>SearchBookmarkFilter</code>) <a class="header-anchor" href="#ブックマーク数フィルター-searchbookmarkfilter" aria-label="Permalink to &quot;ブックマーク数フィルター (`SearchBookmarkFilter`)&quot;">​</a></h3><ul><li><code>None</code>: 指定なし</li><li><code>Bookmark100</code>: 100users 入り以上</li><li><code>Bookmark500</code>: 500users 入り以上</li><li><code>Bookmark1000</code>: 1000users 入り以上</li><li><code>Bookmark5000</code>: 5000users 入り以上</li><li><code>Bookmark10000</code>: 10000users 入り以上</li></ul><hr><h2 id="ウォッチリスト-favoritetagsscreen-watchliststore" tabindex="-1">ウォッチリスト (<code>FavoriteTagsScreen</code> / <code>WatchlistStore</code>) <a class="header-anchor" href="#ウォッチリスト-favoritetagsscreen-watchliststore" aria-label="Permalink to &quot;ウォッチリスト (`FavoriteTagsScreen` / `WatchlistStore`)&quot;">​</a></h2><p>よく使用するタグをウォッチリスト（お気に入りタグ）に登録できます。</p><ul><li>登録データは <code>FavoriteTagEntity</code> テーブルに保存。</li><li>ウォッチリスト画面から各タグの未読・新着作品数を取得し、1 タップで該当タグの検索結果を呼び出し可能。</li><li>タグごとの並び替えおよび個別削除に対応。</li></ul>',17)])])}const g=t(l,[["render",i]]);export{f as __pageData,g as default};
